import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { forgotPassword } from '../services/api';

const ForgotPassword = () => {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!email) {
      setMessage({ type: 'error', text: 'Please enter your email address' });
      return;
    }

    try {
      setLoading(true);
      setMessage({ type: '', text: '' });
      
      await forgotPassword(email);
      setSubmitted(true);
      setMessage({ type: 'success', text: 'Password reset link sent to your email!' });
    } catch (error) {
      setMessage({ 
        type: 'error', 
        text: error.response?.data?.message || 'Error sending reset link' 
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center py-12 px-4">
      <div className="card p-8 max-w-md w-full">
        <div className="text-center mb-6">
          <Link to="/" className="inline-flex items-center space-x-2">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" className="w-12 h-12">
              <defs>
                <linearGradient id="navGrad" x1="0%" y1="0%" x2="0%" y2="100%">
                  <stop offset="0%" stopColor="#0ea5e9"/>
                  <stop offset="100%" stopColor="#0284c7"/>
                </linearGradient>
              </defs>
              <circle cx="50" cy="50" r="45" fill="url(#navGrad)"/>
              <text x="50" y="65" fontFamily="Arial" fontSize="35" fontWeight="bold" fill="white" textAnchor="middle">M</text>
            </svg>
            <span className="text-2xl font-bold text-gray-800">MilkMitra</span>
          </Link>
        </div>

        <h2 className="text-2xl font-bold text-gray-800 text-center mb-2">
          Forgot Password?
        </h2>
        <p className="text-gray-600 text-center mb-6">
          Enter your email address and we'll send you a link to reset your password.
        </p>

        {message.text && (
          <div className={`px-4 py-3 rounded-lg mb-4 ${
            message.type === 'error' 
              ? 'bg-red-100 text-red-700' 
              : 'bg-green-100 text-green-700'
          }`}>
            {message.text}
          </div>
        )}

        {!submitted ? (
          <form onSubmit={handleSubmit}>
            <div className="mb-4">
              <label className="label">Email Address</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="input"
                placeholder="Enter your email"
                required
              />
            </div>

            <button
              type="submit"
              disabled={loading}
              className="btn btn-primary w-full disabled:opacity-50"
            >
              {loading ? 'Sending...' : 'Send Reset Link'}
            </button>
          </form>
        ) : (
          <div className="text-center py-4">
            <p className="text-green-600 font-medium mb-4">
              Check your email for the password reset link!
            </p>
            <button
              onClick={() => setSubmitted(false)}
              className="text-primary-600 hover:text-primary-700"
            >
              Resend email
            </button>
          </div>
        )}

        <div className="mt-6 text-center">
          <Link to="/login" className="text-primary-600 hover:text-primary-700">
            Back to Login
          </Link>
        </div>
      </div>
    </div>
  );
};

export default ForgotPassword;
